func TestExperimentAmbiguousAndSkipped(t *testing.T) {
	loc, err := time.LoadLocation("Europe/Berlin")
	if err != nil {
		t.Fatal(err)
	}
	// Spring forward 2026-03-29 02:00->03:00: 02:30 does not exist.
	skipped := time.Date(2026, 3, 29, 2, 30, 0, 0, loc)
	fmt.Println("skipped local 02:30 ->", skipped.Format("2006-01-02T15:04:05-07:00"), "roundtrip-format:", skipped.Format("2006-01-02T15:04"))

	// Fall back 2026-10-25 03:00->02:00: 02:30 occurs twice.
	ambiguous := time.Date(2026, 10, 25, 2, 30, 0, 0, loc)
	fmt.Println("ambiguous local 02:30 ->", ambiguous.Format("2006-01-02T15:04:05-07:00"), "roundtrip-format:", ambiguous.Format("2006-01-02T15:04"))

	// what is the UTC offset right before vs after on that day
	before := time.Date(2026, 10, 25, 1, 30, 0, 0, loc)
	fmt.Println("before transition 01:30 ->", before.Format("2006-01-02T15:04:05-07:00"))
	after := time.Date(2026, 10, 25, 3, 30, 0, 0, loc)
	fmt.Println("after transition 03:30 ->", after.Format("2006-01-02T15:04:05-07:00"))
}
