with sync_playwright() as p:
    browser = p.chromium.launch()
    for pref in ["no-preference", "reduce"]:
        ctx = browser.new_context(reduced_motion=pref)
        page = ctx.new_page()
        page.goto("http://localhost:18090/", wait_until="networkidle")
        data = page.evaluate("""() => {
            const all = document.querySelectorAll('*');
            let keyframeAnim = 0;
            let transitions = 0;
            let transitionDetails = [];
            for (const el of all) {
                const s = getComputedStyle(el);
                if (s.animationName !== 'none') {
                    keyframeAnim++;
                }
                if (parseFloat(s.transitionDuration) > 0) {
                    transitions++;
                    if (transitionDetails.length < 5) {
                        transitionDetails.push({tag: el.tagName, dur: s.transitionDuration, prop: s.transitionProperty});
                    }
                }
            }
            return {keyframeAnim, transitions, transitionDetails};
        }""")
        print(pref, data)
        ctx.close()
    browser.close()
