func formatDate(y, m, d int) string {
	return padYear(y) + "-" + pad2(m) + "-" + pad2(d)
}

func padYear(y int) string {
	s := itoa(y)
	for len(s) < 4 {
		s = "0" + s
	}
	return s
}

func itoa(n int) string {
	if n == 0 {
		return "0"
	}
	neg := n < 0
	if neg {
